using Microsoft.EntityFrameworkCore;

// Cosmos DB project context — demonstrates EF Core 9 breaking changes for Cosmos provider.
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "SampleDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasPartitionKey(p => p.Category);

            // EF Core 9 breaking change #1: Discriminator property renamed from
            // "Discriminator" to "$type". For existing documents that already store
            // "Discriminator", you must explicitly configure the old property name.
            entity.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

// EF Core 9 breaking change #2: Synchronous I/O on Cosmos DB is no longer supported.
// All sync methods (ToList, First, SaveChanges, etc.) throw InvalidOperationException.
// You must use async equivalents (ToListAsync, FirstAsync, SaveChangesAsync, etc.).
class ProductService
{
    private readonly CosmosDbContext _db;

    public ProductService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 — sync was allowed):
    //   var products = _db.Products.Where(p => p.Category == category).ToList();
    //   _db.SaveChanges();

    // AFTER (EF Core 9 — must be async):
    public async Task<List<Product>> GetByCategoryAsync(string category)
    {
        return await _db.Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }

    public async Task AddProductAsync(Product product)
    {
        _db.Products.Add(product);
        await _db.SaveChangesAsync();
    }
}

